86 class VkCtx
87 {
88     friend class VkCtxScope;
89 
90     enum { QueryCount = 64 * 1024 };
91 
92 public:
93 #if defined TRACY_VK_USE_SYMBOL_TABLE
94     VkCtx( VkInstance instance, VkPhysicalDevice physdev, VkDevice device, VkQueue queue, VkCommandBuffer cmdbuf, PFN_vkGetInstanceProcAddr instanceProcAddr, PFN_vkGetDeviceProcAddr deviceProcAddr, bool calibrated )
95 #else
96     VkCtx( VkPhysicalDevice physdev, VkDevice device, VkQueue queue, VkCommandBuffer cmdbuf, PFN_vkGetPhysicalDeviceCalibrateableTimeDomainsEXT vkGetPhysicalDeviceCalibrateableTimeDomainsEXT, PFN_vkGetCalibratedTimestampsEXT vkGetCalibratedTimestampsEXT)
97 #endif
98         : m_device( device )
99         , m_timeDomain( VK_TIME_DOMAIN_DEVICE_EXT )
100         , m_context( GetGpuCtxCounter().fetch_add( 1, std::memory_order_relaxed ) )
101         , m_head( 0 )
102         , m_tail( 0 )
103         , m_oldCnt( 0 )
104         , m_queryCount( QueryCount )
105 #if !defined TRACY_VK_USE_SYMBOL_TABLE
106         , m_vkGetCalibratedTimestampsEXT( vkGetCalibratedTimestampsEXT )
107 #endif
108     {
109         assert( m_context != 255 );
110 
111 #if defined TRACY_VK_USE_SYMBOL_TABLE
112         PopulateSymbolTable(instance, instanceProcAddr, deviceProcAddr);
113         if ( calibrated )
114         {
115             m_vkGetCalibratedTimestampsEXT = m_symbols.vkGetCalibratedTimestampsEXT;
116         }
117 
118 #endif
119 
120         if( VK_FUNCTION_WRAPPER( vkGetPhysicalDeviceCalibrateableTimeDomainsEXT ) && m_vkGetCalibratedTimestampsEXT )
121         {
122             FindAvailableTimeDomains( physdev, VK_FUNCTION_WRAPPER( vkGetPhysicalDeviceCalibrateableTimeDomainsEXT ) );
123         }
124 
125         CreateQueryPool();
126 
127         VkCommandBufferBeginInfo beginInfo = {};
128         beginInfo.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
129         beginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
130 
131         VkSubmitInfo submitInfo = {};
132         submitInfo.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
133         submitInfo.commandBufferCount = 1;
134         submitInfo.pCommandBuffers = &cmdbuf;
135 
136         VK_FUNCTION_WRAPPER( vkBeginCommandBuffer( cmdbuf, &beginInfo ) );
137         VK_FUNCTION_WRAPPER( vkCmdResetQueryPool( cmdbuf, m_query, 0, m_queryCount ) );
138         VK_FUNCTION_WRAPPER( vkEndCommandBuffer( cmdbuf ) );
139         VK_FUNCTION_WRAPPER( vkQueueSubmit( queue, 1, &submitInfo, VK_NULL_HANDLE ) );
140         VK_FUNCTION_WRAPPER( vkQueueWaitIdle( queue ) );
141 
142         int64_t tcpu, tgpu;
143         if( m_timeDomain == VK_TIME_DOMAIN_DEVICE_EXT )
144         {
145             VK_FUNCTION_WRAPPER( vkBeginCommandBuffer( cmdbuf, &beginInfo ) );
146             VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( cmdbuf, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT, m_query, 0 ) );
147             VK_FUNCTION_WRAPPER( vkEndCommandBuffer( cmdbuf ) );
148             VK_FUNCTION_WRAPPER( vkQueueSubmit( queue, 1, &submitInfo, VK_NULL_HANDLE ) );
149             VK_FUNCTION_WRAPPER( vkQueueWaitIdle( queue ) );
150 
151             tcpu = Profiler::GetTime();
152             VK_FUNCTION_WRAPPER( vkGetQueryPoolResults( device, m_query, 0, 1, sizeof( tgpu ), &tgpu, sizeof( tgpu ), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT ) );
153 
154             VK_FUNCTION_WRAPPER( vkBeginCommandBuffer( cmdbuf, &beginInfo ) );
155             VK_FUNCTION_WRAPPER( vkCmdResetQueryPool( cmdbuf, m_query, 0, 1 ) );
156             VK_FUNCTION_WRAPPER( vkEndCommandBuffer( cmdbuf ) );
157             VK_FUNCTION_WRAPPER( vkQueueSubmit( queue, 1, &submitInfo, VK_NULL_HANDLE ) );
158             VK_FUNCTION_WRAPPER( vkQueueWaitIdle( queue ) );
159         }
160         else
161         {
162             FindCalibratedTimestampDeviation();
163             Calibrate( device, m_prevCalibration, tgpu );
164             tcpu = Profiler::GetTime();
165         }
166 
167         WriteInitialItem( physdev, tcpu, tgpu );
168 
169         m_res = (int64_t*)tracy_malloc( sizeof( int64_t ) * m_queryCount );
170     }
171 
