178 #if defined TRACY_VK_USE_SYMBOL_TABLE
179     VkCtx( VkInstance instance, VkPhysicalDevice physdev, VkDevice device, PFN_vkGetInstanceProcAddr instanceProcAddr, PFN_vkGetDeviceProcAddr deviceProcAddr )
180 #else
181     VkCtx( VkPhysicalDevice physdev, VkDevice device, PFN_vkResetQueryPoolEXT vkResetQueryPool, PFN_vkGetPhysicalDeviceCalibrateableTimeDomainsEXT vkGetPhysicalDeviceCalibrateableTimeDomainsEXT, PFN_vkGetCalibratedTimestampsEXT vkGetCalibratedTimestampsEXT )
182 #endif
183         : m_device( device )
184         , m_timeDomain( VK_TIME_DOMAIN_DEVICE_EXT )
185         , m_context( GetGpuCtxCounter().fetch_add(1, std::memory_order_relaxed) )
186         , m_head( 0 )
187         , m_tail( 0 )
188         , m_oldCnt( 0 )
189         , m_queryCount( QueryCount )
190 #if !defined TRACY_VK_USE_SYMBOL_TABLE
191         , m_vkGetCalibratedTimestampsEXT( vkGetCalibratedTimestampsEXT )
192 #endif
193     {
194         assert( m_context != 255);
195 
196 #if defined TRACY_VK_USE_SYMBOL_TABLE
197         PopulateSymbolTable(instance, instanceProcAddr, deviceProcAddr);
198         m_vkGetCalibratedTimestampsEXT = m_symbols.vkGetCalibratedTimestampsEXT;
199 #endif
200 
201         assert( VK_FUNCTION_WRAPPER( vkResetQueryPool ) != nullptr );
202         assert( VK_FUNCTION_WRAPPER( vkGetPhysicalDeviceCalibrateableTimeDomainsEXT ) != nullptr );
203         assert( VK_FUNCTION_WRAPPER( vkGetCalibratedTimestampsEXT ) != nullptr );
204 
205         FindAvailableTimeDomains( physdev, VK_FUNCTION_WRAPPER( vkGetPhysicalDeviceCalibrateableTimeDomainsEXT ) );
206 
207         // We require a host time domain to be available to properly calibrate.
208         FindCalibratedTimestampDeviation();
209         int64_t tgpu;
210         Calibrate( device, m_prevCalibration, tgpu );
211         int64_t tcpu = Profiler::GetTime();
212 
213         CreateQueryPool();
214         VK_FUNCTION_WRAPPER( vkResetQueryPool( device, m_query, 0, m_queryCount ) );
215 
216         WriteInitialItem( physdev, tcpu, tgpu );
217 
218         m_res = (int64_t*)tracy_malloc( sizeof( int64_t ) * m_queryCount );
219     }
220 #endif
