228     void Name( const char* name, uint16_t len )
229     {
230         auto ptr = (char*)tracy_malloc( len );
231         memcpy( ptr, name, len );
232 
233         auto item = Profiler::QueueSerial();
234         MemWrite( &item->hdr.type, QueueType::GpuContextName );
235         MemWrite( &item->gpuContextNameFat.context, m_context );
236         MemWrite( &item->gpuContextNameFat.ptr, (uint64_t)ptr );
237         MemWrite( &item->gpuContextNameFat.size, len );
238 #ifdef TRACY_ON_DEMAND
239         GetProfiler().DeferItem( *item );
240 #endif
241         Profiler::QueueSerialFinish();
242     }
243 
244     void Collect( VkCommandBuffer cmdbuf )
245     {
246         ZoneScopedC( Color::Red4 );
247 
248         const uint64_t head = m_head.load(std::memory_order_relaxed);
249         if( m_tail == head ) return;
250 
251 #ifdef TRACY_ON_DEMAND
252         if( !GetProfiler().IsConnected() )
253         {
254             VK_FUNCTION_WRAPPER( vkCmdResetQueryPool( cmdbuf, m_query, 0, m_queryCount ) );
255             m_tail = head;
256             m_oldCnt = 0;
257             int64_t tgpu;
258             if( m_timeDomain != VK_TIME_DOMAIN_DEVICE_EXT ) Calibrate( m_device, m_prevCalibration, tgpu );
259             return;
260         }
261 #endif
262         assert( head > m_tail );
263         
264         const unsigned int wrappedTail = (unsigned int)( m_tail % m_queryCount );
265 
266         unsigned int cnt;
267         if( m_oldCnt != 0 )
268         {
269             cnt = m_oldCnt;
270             m_oldCnt = 0;
271         }
272         else
273         {
274             cnt = (unsigned int)( head - m_tail );
275             assert( cnt <= m_queryCount );
276             if( wrappedTail + cnt > m_queryCount )
277             {
278                 cnt = m_queryCount - wrappedTail;
279             }
280         }
281 
282 
283         if( VK_FUNCTION_WRAPPER( vkGetQueryPoolResults( m_device, m_query, wrappedTail, cnt, sizeof( int64_t ) * m_queryCount, m_res, sizeof( int64_t ), VK_QUERY_RESULT_64_BIT ) == VK_NOT_READY ) )
284         {
285             m_oldCnt = cnt;
286             return;
287         }
288 
289         for( unsigned int idx=0; idx<cnt; idx++ )
290         {
291             auto item = Profiler::QueueSerial();
292             MemWrite( &item->hdr.type, QueueType::GpuTime );
293             MemWrite( &item->gpuTime.gpuTime, m_res[idx] );
294             MemWrite( &item->gpuTime.queryId, uint16_t( wrappedTail + idx ) );
295             MemWrite( &item->gpuTime.context, m_context );
296             Profiler::QueueSerialFinish();
297         }
298 
299         if( m_timeDomain != VK_TIME_DOMAIN_DEVICE_EXT )
300         {
301             int64_t tgpu, tcpu;
302             Calibrate( m_device, tcpu, tgpu );
303             const auto refCpu = Profiler::GetTime();
304             const auto delta = tcpu - m_prevCalibration;
305             if( delta > 0 )
306             {
307                 m_prevCalibration = tcpu;
308                 auto item = Profiler::QueueSerial();
309                 MemWrite( &item->hdr.type, QueueType::GpuCalibration );
310                 MemWrite( &item->gpuCalibration.gpuTime, tgpu );
311                 MemWrite( &item->gpuCalibration.cpuTime, refCpu );
312                 MemWrite( &item->gpuCalibration.cpuDelta, delta );
313                 MemWrite( &item->gpuCalibration.context, m_context );
314                 Profiler::QueueSerialFinish();
315             }
316         }
317 
318         VK_FUNCTION_WRAPPER( vkCmdResetQueryPool( cmdbuf, m_query, wrappedTail, cnt ) );
319 
320         m_tail += cnt;
321     }
322 
323 private:
324     tracy_force_inline unsigned int NextQueryId()
325     {
326         const uint64_t id = m_head.fetch_add(1, std::memory_order_relaxed);
327         return id % m_queryCount;
328     }
329 
330     tracy_force_inline uint8_t GetId() const
331     {
332         return m_context;
333     }
334 
335     tracy_force_inline void Calibrate( VkDevice device, int64_t& tCpu, int64_t& tGpu )
336     {
337         assert( m_timeDomain != VK_TIME_DOMAIN_DEVICE_EXT );
338         VkCalibratedTimestampInfoEXT spec[2] = {
339             { VK_STRUCTURE_TYPE_CALIBRATED_TIMESTAMP_INFO_EXT, nullptr, VK_TIME_DOMAIN_DEVICE_EXT },
340             { VK_STRUCTURE_TYPE_CALIBRATED_TIMESTAMP_INFO_EXT, nullptr, m_timeDomain },
341         };
342         uint64_t ts[2];
343         uint64_t deviation;
344         do
345         {
346             m_vkGetCalibratedTimestampsEXT( device, 2, spec, ts, &deviation );
347         }
348         while( deviation > m_deviation );
349 
350 #if defined _WIN32
351         tGpu = ts[0];
352         tCpu = ts[1] * m_qpcToNs;
353 #elif defined __linux__ && defined CLOCK_MONOTONIC_RAW
354         tGpu = ts[0];
355         tCpu = ts[1];
356 #else
357         assert( false );
358 #endif
359     }
360 
361     tracy_force_inline void CreateQueryPool()
362     {
363         VkQueryPoolCreateInfo poolInfo = {};
364         poolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
365         poolInfo.queryCount = m_queryCount;
366         poolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
367         while ( VK_FUNCTION_WRAPPER( vkCreateQueryPool( m_device, &poolInfo, nullptr, &m_query ) != VK_SUCCESS ) )
368         {
369             m_queryCount /= 2;
370             poolInfo.queryCount = m_queryCount;
371         }
372     }
373 
374     tracy_force_inline void FindAvailableTimeDomains( VkPhysicalDevice physicalDevice, PFN_vkGetPhysicalDeviceCalibrateableTimeDomainsEXT _vkGetPhysicalDeviceCalibrateableTimeDomainsEXT )
375     {
376         uint32_t num;
377         _vkGetPhysicalDeviceCalibrateableTimeDomainsEXT( physicalDevice, &num, nullptr );
378         if(num > 4) num = 4;
379         VkTimeDomainEXT data[4];
380         _vkGetPhysicalDeviceCalibrateableTimeDomainsEXT( physicalDevice, &num, data );
381         VkTimeDomainEXT supportedDomain = (VkTimeDomainEXT)-1;
382 #if defined _WIN32
383         supportedDomain = VK_TIME_DOMAIN_QUERY_PERFORMANCE_COUNTER_EXT;
384 #elif defined __linux__ && defined CLOCK_MONOTONIC_RAW
385         supportedDomain = VK_TIME_DOMAIN_CLOCK_MONOTONIC_RAW_EXT;
386 #endif
387         for( uint32_t i=0; i<num; i++ ) {
388             if(data[i] == supportedDomain) {
389                 m_timeDomain = data[i];
390                 break;
391             }
392         }
393     }
394 
395     tracy_force_inline void FindCalibratedTimestampDeviation()
396     {
397         assert( m_timeDomain != VK_TIME_DOMAIN_DEVICE_EXT );
398         constexpr size_t NumProbes = 32;
399         VkCalibratedTimestampInfoEXT spec[2] = {
400             { VK_STRUCTURE_TYPE_CALIBRATED_TIMESTAMP_INFO_EXT, nullptr, VK_TIME_DOMAIN_DEVICE_EXT },
401             { VK_STRUCTURE_TYPE_CALIBRATED_TIMESTAMP_INFO_EXT, nullptr, m_timeDomain },
402         };
403         uint64_t ts[2];
404         uint64_t deviation[NumProbes];
405         for( int i=0; i<NumProbes; i++ ) {
406             m_vkGetCalibratedTimestampsEXT( m_device, 2, spec, ts, deviation + i );
407         }
408         uint64_t minDeviation = deviation[0];
409         for( int i=1; i<NumProbes; i++ ) {
410             if ( minDeviation > deviation[i] ) {
411                 minDeviation = deviation[i];
412             }
413         }
414         m_deviation = minDeviation * 3 / 2;
415 
416 #if defined _WIN32
417         m_qpcToNs = int64_t( 1000000000. / GetFrequencyQpc() );
418 #endif
419     }
420 
421     tracy_force_inline void WriteInitialItem( VkPhysicalDevice physdev, int64_t tcpu, int64_t tgpu )
422     {
423         uint8_t flags = 0;
424         if( m_timeDomain != VK_TIME_DOMAIN_DEVICE_EXT ) flags |= GpuContextCalibration;
425 
426         VkPhysicalDeviceProperties prop;
427         VK_FUNCTION_WRAPPER( vkGetPhysicalDeviceProperties( physdev, &prop ) );
428         const float period = prop.limits.timestampPeriod;
429 
430         auto item = Profiler::QueueSerial();
431         MemWrite( &item->hdr.type, QueueType::GpuNewContext );
432         MemWrite( &item->gpuNewContext.cpuTime, tcpu );
433         MemWrite( &item->gpuNewContext.gpuTime, tgpu );
434         memset( &item->gpuNewContext.thread, 0, sizeof( item->gpuNewContext.thread ) );
435         MemWrite( &item->gpuNewContext.period, period );
436         MemWrite( &item->gpuNewContext.context, m_context );
437         MemWrite( &item->gpuNewContext.flags, flags );
438         MemWrite( &item->gpuNewContext.type, GpuContextType::Vulkan );
439 
440 #ifdef TRACY_ON_DEMAND
441         GetProfiler().DeferItem( *item );
442 #endif
443         Profiler::QueueSerialFinish();
444     }
445 
446 #if defined TRACY_VK_USE_SYMBOL_TABLE
447     void PopulateSymbolTable( VkInstance instance, PFN_vkGetInstanceProcAddr instanceProcAddr, PFN_vkGetDeviceProcAddr deviceProcAddr )
448     {
449 #define VK_GET_DEVICE_SYMBOL( name ) \
450         (PFN_##name)deviceProcAddr( m_device, #name );
451 #define VK_LOAD_DEVICE_SYMBOL( name ) \
452         m_symbols.name = VK_GET_DEVICE_SYMBOL( name );
453 #define VK_GET_INSTANCE_SYMBOL( name ) \
454         (PFN_##name)instanceProcAddr( instance, #name );
455 #define VK_LOAD_INSTANCE_SYMBOL( name ) \
456         m_symbols.name = VK_GET_INSTANCE_SYMBOL( name );
457 
458         LoadVkDeviceCoreSymbols( VK_LOAD_DEVICE_SYMBOL )
459         LoadVkDeviceExtensionSymbols( VK_LOAD_DEVICE_SYMBOL )
460         LoadVkInstanceCoreSymbols( VK_LOAD_INSTANCE_SYMBOL )
461 #undef VK_GET_DEVICE_SYMBOL
462 #undef VK_LOAD_DEVICE_SYMBOL
463 #undef VK_GET_INSTANCE_SYMBOL
464 #undef VK_LOAD_INSTANCE_SYMBOL
465     }
466 #endif
467 
468     VkDevice m_device;
469     VkQueryPool m_query;
470     VkTimeDomainEXT m_timeDomain;
471 #if defined TRACY_VK_USE_SYMBOL_TABLE
472     VkSymbolTable m_symbols;
473 #endif
474     uint64_t m_deviation;
475     int64_t m_qpcToNs;
476     int64_t m_prevCalibration;
477     uint8_t m_context;
478 
479     std::atomic<uint64_t> m_head;
480     uint64_t m_tail;
481     unsigned int m_oldCnt;
482     unsigned int m_queryCount;
483 
484     int64_t* m_res;
485 
486     PFN_vkGetCalibratedTimestampsEXT m_vkGetCalibratedTimestampsEXT;
487 };
