489 class VkCtxScope
490 {
491 public:
492     tracy_force_inline VkCtxScope( VkCtx* ctx, const SourceLocationData* srcloc, VkCommandBuffer cmdbuf, bool is_active )
493 #ifdef TRACY_ON_DEMAND
494         : m_active( is_active && GetProfiler().IsConnected() )
495 #else
496         : m_active( is_active )
497 #endif
498     {
499         if( !m_active ) return;
500         m_cmdbuf = cmdbuf;
501         m_ctx = ctx;
502 
503         const auto queryId = ctx->NextQueryId();
504         CONTEXT_VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( cmdbuf, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, ctx->m_query, queryId ) );
505 
506         auto item = Profiler::QueueSerial();
507         MemWrite( &item->hdr.type, QueueType::GpuZoneBeginSerial );
508         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
509         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
510         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
511         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
512         MemWrite( &item->gpuZoneBegin.context, ctx->GetId() );
513         Profiler::QueueSerialFinish();
514     }
515 
516     tracy_force_inline VkCtxScope( VkCtx* ctx, const SourceLocationData* srcloc, VkCommandBuffer cmdbuf, int depth, bool is_active )
517 #ifdef TRACY_ON_DEMAND
518         : m_active( is_active && GetProfiler().IsConnected() )
519 #else
520         : m_active( is_active )
521 #endif
522     {
523         if( !m_active ) return;
524         m_cmdbuf = cmdbuf;
525         m_ctx = ctx;
526 
527         const auto queryId = ctx->NextQueryId();
528         CONTEXT_VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( cmdbuf, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, ctx->m_query, queryId ) );
529 
530         auto item = Profiler::QueueSerialCallstack( Callstack( depth ) );
531         MemWrite( &item->hdr.type, QueueType::GpuZoneBeginCallstackSerial );
532         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
533         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
534         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
535         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
536         MemWrite( &item->gpuZoneBegin.context, ctx->GetId() );
537         Profiler::QueueSerialFinish();
538     }
