540     tracy_force_inline VkCtxScope( VkCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, VkCommandBuffer cmdbuf, bool is_active )
541 #ifdef TRACY_ON_DEMAND
542         : m_active( is_active && GetProfiler().IsConnected() )
543 #else
544         : m_active( is_active )
545 #endif
546     {
547         if( !m_active ) return;
548         m_cmdbuf = cmdbuf;
549         m_ctx = ctx;
550 
551         const auto queryId = ctx->NextQueryId();
552         CONTEXT_VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( cmdbuf, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, ctx->m_query, queryId ) );
553 
554         const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
555         auto item = Profiler::QueueSerial();
556         MemWrite( &item->hdr.type, QueueType::GpuZoneBeginAllocSrcLocSerial );
557         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
558         MemWrite( &item->gpuZoneBegin.srcloc, srcloc );
559         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
560         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
561         MemWrite( &item->gpuZoneBegin.context, ctx->GetId() );
562         Profiler::QueueSerialFinish();
563     }
564 
565     tracy_force_inline VkCtxScope( VkCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, VkCommandBuffer cmdbuf, int depth, bool is_active )
566 #ifdef TRACY_ON_DEMAND
567         : m_active( is_active && GetProfiler().IsConnected() )
568 #else
569         : m_active( is_active )
570 #endif
571     {
572         if( !m_active ) return;
573         m_cmdbuf = cmdbuf;
574         m_ctx = ctx;
575 
576         const auto queryId = ctx->NextQueryId();
577         CONTEXT_VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( cmdbuf, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, ctx->m_query, queryId ) );
578 
579         const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
580         auto item = Profiler::QueueSerialCallstack( Callstack( depth ) );
581         MemWrite( &item->hdr.type, QueueType::GpuZoneBeginAllocSrcLocCallstackSerial );
582         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
583         MemWrite( &item->gpuZoneBegin.srcloc, srcloc );
584         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
585         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
586         MemWrite( &item->gpuZoneBegin.context, ctx->GetId() );
587         Profiler::QueueSerialFinish();
588     }
589 
590     tracy_force_inline ~VkCtxScope()
591     {
592         if( !m_active ) return;
593 
594         const auto queryId = m_ctx->NextQueryId();
595         CONTEXT_VK_FUNCTION_WRAPPER( vkCmdWriteTimestamp( m_cmdbuf, VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT, m_ctx->m_query, queryId ) );
596 
597         auto item = Profiler::QueueSerial();
598         MemWrite( &item->hdr.type, QueueType::GpuZoneEndSerial );
599         MemWrite( &item->gpuZoneEnd.cpuTime, Profiler::GetTime() );
600         MemWrite( &item->gpuZoneEnd.thread, GetThreadHandle() );
601         MemWrite( &item->gpuZoneEnd.queryId, uint16_t( queryId ) );
602         MemWrite( &item->gpuZoneEnd.context, m_ctx->GetId() );
603         Profiler::QueueSerialFinish();
604     }
605 
606 private:
607     const bool m_active;
608 
609     VkCommandBuffer m_cmdbuf;
610     VkCtx* m_ctx;
611 };
